const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const projectId = String(payload.projectId || payload.id || 'prj-active').trim();
const clientName = String(payload.clientName || payload.client || 'Client Executive').trim();
const clientEmail = String(payload.clientEmail || payload.email || '').trim().toLowerCase();
const projectName = String(payload.projectName || payload.title || 'Enterprise Platform Engineering').trim();
const currentMilestone = String(payload.currentMilestone || 'M2').toUpperCase();
const progressPercent = Number(payload.progressPercent || 50);

const completedTasks = Array.isArray(payload.completedTasks) ? payload.completedTasks : [
  'Implemented responsive frontend dashboard layout',
  'Integrated secure Supabase authentication & session handlers',
  'Provisioned automated CI/CD pipeline with Playwright test coverage'
];

const upcomingTasks = Array.isArray(payload.upcomingTasks) ? payload.upcomingTasks : [
  'Connect real-time websocket data streams for analytics charts',
  'Execute load testing and sub-120ms latency optimization',
  'Deploy staging release candidate for stakeholder acceptance review'
];

const blockers = Array.isArray(payload.blockers) ? payload.blockers : [];
const projectHealth = blockers.length === 0 ? 'ON_TRACK' : (blockers.length === 1 ? 'MONITORED_RISK' : 'NEEDS_ATTENTION');

const projectSnapshot = {
  projectId,
  clientName,
  clientEmail,
  projectName,
  currentMilestone,
  progressPercent,
  projectHealth,
  completedTasks,
  upcomingTasks,
  blockers,
  reportingPeriod: 'Weekly Digest (Monday 09:00 IST)',
  generatedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    projectSnapshot
  }
}];

const item = $input.first().json;
const p = item.projectSnapshot;

const executiveSummary = `During this reporting cycle, the team advanced ${p.projectName} to ${p.progressPercent}% completion within milestone ${p.currentMilestone}. Overall health status is evaluated as ${p.projectHealth}. ${p.completedTasks.length} core deliverables were verified and staged for review.`;

const digest = {
  greeting: `Dear ${p.clientName},`,
  headline: `Weekly Project Progress Update: ${p.projectName}`,
  executiveSummary,
  milestoneStatus: `Milestone ${p.currentMilestone} in progress (${p.progressPercent}% overall complete)`,
  achievementsThisWeek: p.completedTasks,
  targetDeliverablesNextWeek: p.upcomingTasks,
  blockersResolved: p.blockers.length > 0 ? p.blockers : ['No operational blockers identified'],
  nextSyncSchedule: 'Weekly Standup Demo - Wednesdays 14:00 IST',
  meetingPrompt: 'Schedule or adjust standup via calendar.google.com'
};

return [{
  json: {
    ...item,
    digest
  }
}];

const item = $input.first().json;
const p = item.projectSnapshot;
const d = item.digest;

const emailSubject = `[LIT Progress Report] ${p.projectName} — Week Status: ${p.projectHealth}`;
const textBody = `${d.greeting}\n\n${d.executiveSummary}\n\nKey Deliverables Staged:\n${d.achievementsThisWeek.map(t => '• ' + t).join('\n')}\n\nUpcoming Objectives:\n${d.targetDeliverablesNextWeek.map(t => '• ' + t).join('\n')}\n\nHealth: ${p.projectHealth}\nLead Engineer: Vikash Saravanan\nLogic Intelligence Technologies`;

const emailPayload = {
  recipient: p.clientEmail || 'delivery@logicintelligencetechnologies.com',
  subject: emailSubject,
  previewText: `${p.projectName} is at ${p.progressPercent}% completion (${p.projectHealth}).`,
  textBody,
  dispatchStatus: 'QUEUED_FOR_OUTBOUND_SMTP',
  dispatchedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'report_dispatched',
    projectId: p.projectId,
    projectSnapshot: p,
    emailPayload
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'report_dispatched',
  detail: {
    projectId: item.json.projectId,
    projectSnapshot: item.json.projectSnapshot,
    emailPayload: item.json.emailPayload
  }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
